import numpy as np

def pass_at_k(ns, cs, k):
    vals = []
    for n, c in zip(ns, cs):
        if n - c < k:
            vals.append(1.0)
        else:
            vals.append(float(1.0 - np.prod(1.0 - k / np.arange(n - c + 1, n + 1))))
    return {"per_problem": vals, "mean": float(np.mean(vals))}
